A(17,30,'alex','ficha','garantia',("Pantalla partida: tira en la fosa izquierda, parche en la derecha; reloj 23:00","Tira vs parche. 8 horas.","Tira en el lado izquierdo, parche en el derecho. Ocho horas. Mira."),[(8,"Time-lapse de la noche; reloj 7:00; retirada de ambos","Resultado","La tira: roja y con pelusa. El parche: blanco de grasa y la piel lisa. Mismo poro, misma noche.","Comparativa directa; racional (R5) y demostrativa (R28).")],None,None,None,1,None,[(5,"argumento racional para Álex"),(28,"demostración en directo")],[("comparativa","Tira contra parche. Ocho horas. Mira."),("reto","Mismo poro, misma noche. A ver cuál gana."),("pregunta","¿Tira o parche? Lo probé en la misma nariz.")],"Experimento controlado en 30 s: Álex compra por comparación. El plano de retirada doble es el peel reveal (R28) con contraste incorporado.")
A(18,35,'bea','adv','garantia',("Bea con un exfoliante en la mano, cara de duda","¿Te exfolias a diario?","Si te exfolias todos los días para quitar lo de la nariz, estás haciendo que vuelva más fuerte."),[(6,"Animación: piel agredida produce más grasa","Más agresión = más grasa","Cuando agredes la piel, fabrica más grasa para defenderse. Más exfoliante, más brillo, más puntitos.","Objeción de Bea (usa exfoliantes) con la explicación de R46 («your skin panics»).")],None,None,0,0,None,[(46,"«tu piel entra en pánico y produce más grasa» sin claims"),(3,"«cuanto más los atacas, peor»")],[("condición","Si te exfolias a diario, lo estás empeorando."),("contradicción","Exfoliar más no quita los puntitos. Los multiplica."),("pregunta","¿Cuántas veces a la semana te exfolias la nariz?")],"Ataca el hábito de Bea (exfoliante diario) con el mecanismo de defensa de la piel. Vende el parche como «dos noches por semana», no como un producto más.")
A(19,25,'bea','ficha','garantia',("POV: sacacomedones de acero cayendo a la basura","A la basura","Tiré el sacacomedones. Esto lo sustituye sin dejar marca."),[(5,"Macro: marca roja de la herramienta / nariz lisa tras el parche","Sin marca","La herramienta deja marca. El parche, no. Y saca más.","Objeto reconocible + contraste.")],None,None,1,0,None,[(33,"herramientas de extracción de TikTok como error de Bea"),(4,"sin rojeces")],[("gesto","Tiré el sacacomedones. Esto lo sustituye."),("orden","Deja la herramienta. Ponte esto."),("pregunta","¿Sigues usando el sacacomedones de TikTok?")],"El gesto de tirar algo engancha en 2 s. Habla el idioma de Bea (herramientas virales) y resuelve la objeción «deja marca».")
